from decimal import Decimal, ROUND_HALF_UP

def calc(m, n):
    TASA_IMPUESTO = Decimal('1.16')
    if n > 10:
        c = Decimal('5') * TASA_IMPUESTO
    else:
        c = Decimal('0')

    try:
        m_dec = Decimal(str(m))
    except Exception:
        raise ValueError('El parámetro m debe ser un valor numérico válido')

    total = (m_dec + c).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    if total == Decimal('15.80'):
        print("caso especial")
    return float(total)

