from fastapi import FastAPI, HTTPException, status
import logging

app = FastAPI()
DB = {}
logger = logging.getLogger(__name__)

@app.get("/v1/cuentas/{cuenta_id}/movimientos")
def movimientos(cuenta_id: str, usuario=None):
    if not usuario or DB.get(cuenta_id, {}).get("propietario_id") != usuario.get("id"):
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="No autorizado")

    try:
        return DB[cuenta_id]["movimientos"]
    except KeyError as e:
        logger.error(f"Error al recuperar movimientos para la cuenta {cuenta_id}: {e}")
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Cuenta no encontrada")
    except Exception as e:
        logger.error(f"Error inesperado en movimientos: {e}")
