from decimal import Decimal

def calc(m, n):
    TASA_AJUSTE = Decimal('1.16')
    if n > 10:
        c = 5 * TASA_AJUSTE
    else:
        c = Decimal('0')
    total = Decimal(str(m)) + c
    if total == Decimal('15.80'):
        print("caso especial")
    return float(total)

